#pragma once

inline constexpr char kRobotWebControlPage[] = R"CONTROL(<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<meta name="theme-color" content="#0b0906">
<title>Xiaozhi Desk Robot</title>
<style>
:root{--bg:#090806;--panel:#17120b;--line:#4b3b25;--line2:#302617;--brass:#c6a15b;--hi:#e3c27b;--text:#f2eadc;--muted:#8f7b5a;--red:#d8655b;--green:#53c58b;--yellow:#d8af52;--blue:#559bd8;--gap:10px;--shadow:rgba(0,0,0,.42)}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:ui-rounded,"SF Pro Rounded","Segoe UI",sans-serif}body{min-height:100dvh;background:radial-gradient(circle at 45% -25%,#3a2d19 0,transparent 42%),linear-gradient(180deg,#0e0b07,var(--bg));padding:clamp(12px,1.3vw,22px)}button,input,select{font:inherit}.app{width:100%;min-height:calc(100dvh - 24px)}
header{height:50px;display:flex;align-items:center;justify-content:space-between;margin:0 2px 13px}.brand{display:flex;align-items:center;gap:12px}.mark{width:42px;height:42px;border:1px solid var(--line);border-radius:14px;background:linear-gradient(145deg,#2a2114,#100d08);display:grid;place-items:center;box-shadow:0 8px 24px var(--shadow)}.eyes{display:flex;gap:4px}.eyes i{display:block;width:9px;height:7px;border-radius:3px;background:var(--hi);box-shadow:0 0 10px rgba(227,194,123,.28)}h1{font-size:18px;line-height:1.1;margin:0}.sub{font-size:10px;color:var(--muted);margin-top:4px;letter-spacing:.8px;text-transform:uppercase}.online{display:flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:11px;background:rgba(20,16,10,.8)}.online i,.dot{width:8px;height:8px;border-radius:50%;background:var(--muted);box-shadow:0 0 0 3px rgba(143,123,90,.12)}.online.ok{color:#a9d9bd;border-color:#315f48}.online.ok i{background:var(--green)}
.dashboard{display:grid;grid-template-columns:minmax(280px,.74fr) minmax(390px,.96fr) minmax(500px,1.3fr);gap:var(--gap);align-items:start;min-height:calc(100dvh - 87px)}.column{display:flex;min-width:0;flex-direction:column;gap:var(--gap)}.right-column{height:calc(100dvh - 87px)}.card{position:relative;border:1px solid var(--line);border-radius:18px;background:linear-gradient(160deg,rgba(31,24,15,.96),rgba(17,14,9,.98));box-shadow:0 14px 34px var(--shadow),inset 0 1px rgba(255,255,255,.025);padding:17px;overflow:hidden}.card:before{content:"";position:absolute;inset:0 auto auto 15%;width:70%;height:1px;background:linear-gradient(90deg,transparent,var(--brass),transparent);opacity:.32}.section-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:13px}.section-title strong{font-size:12px;letter-spacing:.8px;text-transform:uppercase}.section-title span{color:var(--hi);font-size:11px}
.status{display:grid;grid-template-columns:1fr 1fr;gap:9px}.metric{padding:11px 12px;border-radius:12px;background:rgba(6,5,3,.48);border:1px solid var(--line2);min-width:0}.metric.wide{grid-column:1/-1}.label{font-size:9px;letter-spacing:.9px;text-transform:uppercase;color:var(--muted)}.value{margin-top:5px;font-size:13px;color:var(--hi);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.health{display:flex;gap:7px;align-items:center}.health .dot{width:7px;height:7px;box-shadow:none}.health.good .dot{background:var(--green)}.health.bad .dot{background:var(--red)}
.safety{display:none;border-color:#81453e;background:linear-gradient(145deg,#321713,#1a0d09);color:#ffc0b8}.safety.show{display:flex;align-items:center;justify-content:space-between;gap:13px}.safety b{display:block;font-size:13px}.safety small{display:block;color:#cf8b82;font-size:10px;margin-top:4px}.safety button{border:1px solid #a85a50;border-radius:10px;background:#491e19;color:#ffd4ce;padding:9px 11px;font-size:11px;font-weight:800}
.dpad{display:grid;grid-template-columns:repeat(3,74px);grid-template-rows:repeat(3,63px);justify-content:center;gap:8px;margin:0 0 13px}.control{border:1px solid #5e492b;color:var(--hi);background:linear-gradient(145deg,#282014,#141008);border-radius:16px;box-shadow:0 6px 14px var(--shadow),inset 0 1px rgba(255,255,255,.04);cursor:pointer;touch-action:none;transition:transform .12s,border-color .12s,background .12s,opacity .12s}.control:active,.control.active{transform:scale(.94);border-color:var(--hi);background:#322716}.control:disabled{cursor:not-allowed;opacity:.28;filter:saturate(.3)}.control svg{width:23px;height:23px;fill:currentColor}.up{grid-column:2}.left{grid-column:1;grid-row:2}.stop{grid-column:2;grid-row:2;border-color:#753a33;color:#ffaaa2;background:linear-gradient(145deg,#351815,#1b0c0a);font-size:11px;font-weight:800;letter-spacing:1.2px}.right{grid-column:3;grid-row:2}.down{grid-column:2;grid-row:3}.down svg{transform:rotate(180deg)}.left svg{transform:rotate(-90deg)}.right svg{transform:rotate(90deg)}.range-row{display:grid;grid-template-columns:42px 1fr 47px;align-items:center;gap:9px;color:var(--muted);font-size:10px}input[type=range]{appearance:none;width:100%;height:5px;border-radius:4px;background:#3a2d1c;outline:0}input[type=range]::-webkit-slider-thumb{appearance:none;width:19px;height:19px;border-radius:50%;background:var(--hi);border:4px solid #392b18;box-shadow:0 2px 8px #000}.motor-state{display:flex;justify-content:space-between;gap:8px;margin-top:13px;padding-top:11px;border-top:1px solid var(--line2);color:var(--muted);font-size:10px}.motor-state b{color:var(--hi);font-weight:600}.progress{height:5px;border-radius:4px;background:#2e2417;overflow:hidden;margin-top:9px}.progress i{display:block;width:0;height:100%;background:linear-gradient(90deg,var(--brass),var(--hi));transition:width .25s}
.audio-row{display:grid;grid-template-columns:102px 1fr 40px;align-items:center;gap:9px;padding:10px 0}.audio-row+.audio-row{border-top:1px solid var(--line2)}.audio-name b{display:block;font-size:11px}.audio-name small{display:block;color:var(--muted);font-size:9px;margin-top:3px}.audio-value{text-align:right;color:var(--hi);font-size:11px;font-variant-numeric:tabular-nums}.vu-wrap{grid-column:2/4;display:flex;align-items:center;gap:7px;margin-top:-2px}.vu{flex:1;height:6px;border-radius:5px;background:#2e2417;overflow:hidden}.vu i{display:block;width:0;height:100%;background:linear-gradient(90deg,var(--green) 0 68%,var(--yellow) 82%,var(--red));transition:width .09s}.clip{font-size:9px;color:var(--muted)}.clip.on{color:#ff8d82;font-weight:800}
.actions{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.action{min-height:58px;border:1px solid var(--line);border-radius:13px;background:#17120b;color:#e8dcc6;padding:10px 11px;display:flex;align-items:center;gap:10px;text-align:left;cursor:pointer;transition:.14s}.action:active{transform:scale(.97);background:#2a2114}.action .icon{width:31px;height:31px;border-radius:10px;background:#2b2113;color:var(--hi);display:grid;place-items:center;font-size:15px;flex:0 0 auto}.action b{display:block;font-size:11px}.action small{display:block;color:var(--muted);font-size:9px;margin-top:3px}.action.danger{border-color:#643a30}.action.danger .icon{color:#ff9c90;background:#321713}.action.on{border-color:#7c6337;background:#241c10}.action.on .icon{background:var(--brass);color:#130f08;box-shadow:0 0 16px rgba(198,161,91,.2)}
.threshold{margin-top:11px;padding-top:11px;border-top:1px solid var(--line2)}.threshold-head{display:flex;justify-content:space-between;margin-bottom:9px;font-size:10px;color:var(--muted)}.threshold-head b{color:var(--hi)}
.capacity-test{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center;margin-top:11px;padding:11px 12px;border:1px solid var(--line2);border-radius:12px;background:rgba(6,5,3,.48)}.capacity-result b{display:block;color:var(--hi);font-size:13px;font-variant-numeric:tabular-nums}.capacity-result small{display:block;margin-top:4px;color:var(--muted);font-size:9px}.capacity-buttons{display:flex;gap:6px}.capacity-buttons button{border:1px solid var(--line);border-radius:9px;background:#21190f;color:var(--hi);padding:8px 10px;font-size:9px;cursor:pointer}.capacity-buttons button:disabled{opacity:.35;cursor:not-allowed}.capacity-buttons button.on{background:var(--brass);color:#171006}.capacity-buttons .reset{color:#ffaaa2;border-color:#643a30;background:#28110f}
.camera-body{display:grid;grid-template-columns:minmax(170px,1.15fr) minmax(140px,.7fr);gap:12px;align-items:stretch}.snapshot{min-height:0;aspect-ratio:4/3;border:1px dashed #55442a;border-radius:13px;background:#080705;display:grid;place-items:center;overflow:hidden;color:var(--muted);font-size:10px;text-align:center}.snapshot img{display:none;width:100%;height:100%;object-fit:cover}.snapshot.has-image img{display:block}.snapshot.has-image span{display:none}.camera-copy{display:flex;min-width:0;flex-direction:column;justify-content:center;gap:10px}.camera-copy p{margin:0;color:var(--muted);font-size:10px;line-height:1.5}.camera-buttons{display:grid;grid-template-columns:1fr;gap:8px}.mini-button{width:100%;border:1px solid var(--line);border-radius:10px;background:#21190f;color:var(--hi);padding:10px 12px;font-size:10px;cursor:pointer}.mini-button.on{background:var(--brass);color:#171006}.mini-button:disabled{opacity:.45}.camera-meta{font-size:9px;color:var(--muted)}
.emotion-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}.emotion{border:1px solid var(--line2);border-radius:10px;background:#100d08;color:#d9c8a8;padding:9px 6px;font-size:9px;text-transform:capitalize;cursor:pointer;transition:.14s}.emotion:hover{border-color:#6b5432;color:var(--hi)}.emotion:active{transform:scale(.96)}.emotion.on{border-color:var(--brass);background:#2a2114;color:var(--hi);box-shadow:inset 0 0 0 1px rgba(227,194,123,.12)}
.device-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.device-row{min-width:0;padding:9px 10px;border:1px solid var(--line2);border-radius:11px;background:rgba(6,5,3,.42)}.device-row span{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.6px}.device-row b{display:block;margin-top:5px;color:#d9c8a8;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.display-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:12px}.display-settings{display:grid;grid-template-columns:1fr 1fr;gap:9px}.field{display:flex;min-width:0;flex-direction:column;gap:6px}.field.wide{grid-column:1/-1}.field>span{color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.6px}.text-input,.field select{width:100%;min-width:0;border:1px solid var(--line2);border-radius:10px;background:#0d0a06;color:var(--text);padding:9px 10px;font-size:11px;outline:0}.text-input:focus,.field select:focus{border-color:var(--brass)}.segment-toggles{grid-column:1/-1;display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.toggle{display:flex;align-items:center;gap:7px;border:1px solid var(--line2);border-radius:10px;background:#0d0a06;color:#d9c8a8;padding:9px;font-size:10px;cursor:pointer}.toggle input{width:15px;height:15px;margin:0;accent-color:var(--brass)}
.log-card{padding:0;overflow:hidden;display:flex;flex-direction:column;height:100%;min-height:520px}.log-head{display:flex;align-items:center;justify-content:space-between;gap:9px;padding:12px 13px;border-bottom:1px solid var(--line2)}.log-state{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:10px;letter-spacing:.7px;text-transform:uppercase}.log-state i{width:7px;height:7px;border-radius:50%;background:var(--green)}.log-tools{display:flex;gap:7px;align-items:center}.log-button,.log-select,.log-search{border:1px solid var(--line);border-radius:8px;background:#17120b;color:var(--hi);padding:7px 9px;font-size:10px}.log-search{width:min(15vw,165px);color:var(--text);outline:0}.log-search::placeholder{color:#66573e}.log-button{cursor:pointer}.badge{display:none;min-width:19px;padding:3px 5px;border-radius:999px;background:#54231f;color:#ffaaa2;text-align:center;font-size:9px}.badge.show{display:inline-block}.log-output{margin:0;flex:1;min-height:0;padding:13px;overflow:auto;background:#070604;color:#d9c8a8;font:10px/1.52 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;tab-size:2}.log-foot{display:flex;align-items:center;justify-content:space-between;padding:10px 13px;color:var(--muted);font-size:10px;border-top:1px solid var(--line2)}.auto-scroll{display:flex;align-items:center;gap:6px}.auto-scroll input{accent-color:var(--brass)}
.hint{text-align:center;color:#635640;font-size:9px;line-height:1.4;margin:3px 8px 0}.panic-stop{position:fixed;right:18px;bottom:18px;z-index:9;display:none;border:1px solid #a85a50;border-radius:999px;background:#491e19;color:#ffd4ce;padding:12px 17px;font-size:11px;font-weight:900;box-shadow:0 10px 32px #000}.panic-stop.show{display:block;animation:pulse 1s infinite alternate}@keyframes pulse{to{box-shadow:0 0 0 5px rgba(216,101,91,.14),0 10px 32px #000}}.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,16px);opacity:0;pointer-events:none;background:#2a2114;border:1px solid var(--brass);color:#f4e7ce;border-radius:999px;padding:10px 15px;font-size:11px;box-shadow:0 10px 30px #000;transition:.2s;max-width:calc(100% - 32px);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;z-index:10}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:1280px){.dashboard{grid-template-columns:1fr 1fr}.right-column{grid-column:1/-1;height:min(58dvh,580px)}.log-card{min-height:380px}.log-search{width:165px}}
@media(max-width:700px){body{padding:12px 10px 74px}.app{width:100%}header{margin-bottom:10px}.sub{letter-spacing:.45px}.dashboard{grid-template-columns:1fr;gap:10px}.right-column{grid-column:auto;height:54dvh;min-height:380px}.card{border-radius:16px}.actions{grid-template-columns:1fr 1fr}.camera-body{grid-template-columns:1fr}.snapshot{min-height:170px}.emotion-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.log-head{align-items:flex-start}.log-tools{flex-wrap:wrap;justify-content:flex-end}.log-search{width:120px}.panic-stop{right:12px;bottom:12px}.hint{margin-bottom:8px}}
@media(max-width:380px){.dpad{grid-template-columns:repeat(3,62px);grid-template-rows:repeat(3,54px)}.actions,.display-actions,.display-settings{grid-template-columns:1fr}.status,.device-grid{grid-template-columns:1fr}.metric.wide,.field.wide,.segment-toggles{grid-column:auto}.segment-toggles{grid-template-columns:1fr}.emotion-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.audio-row{grid-template-columns:82px 1fr 34px}.capacity-test{grid-template-columns:1fr}.capacity-buttons{display:grid;grid-template-columns:repeat(3,1fr)}}
</style>
</head>
<body>
<main class="app">
<header><div class="brand"><div class="mark"><span class="eyes"><i></i><i></i></span></div><div><h1>Xiaozhi Desk Robot</h1><div class="sub">Local control · port 8080</div></div></div><div id="online" class="online"><i></i><span>Connecting</span></div></header>
<div class="dashboard">
<div class="column left-column">
<section class="card"><div class="section-title"><strong>Robot status</strong><span id="uptime">—</span></div><div class="status"><div class="metric"><div class="label">Assistant</div><div class="value" id="state">—</div></div><div class="metric"><div class="label">Camera</div><div class="value" id="camera">—</div></div><div class="metric"><div class="label">Floor distance</div><div class="value" id="distance">—</div></div><div class="metric"><div class="label">Cliff sensor</div><div class="value" id="rangeState">Checking</div></div><div class="metric"><div class="label">Battery</div><div class="value" id="battery">Checking</div></div><div class="metric"><div class="label">Current · power</div><div class="value" id="power">—</div></div><div class="metric wide"><div class="label">Motion sensor</div><div class="value" id="motionSensor">Checking</div></div><div class="metric wide"><div class="label">Secondary OLED</div><div class="value health" id="oledState"><i class="dot"></i><span>Checking</span></div></div></div><div class="capacity-test"><div class="capacity-result"><b id="capacityResult">0.0 mAh</b><small id="capacityState">Capacity test not started</small></div><div class="capacity-buttons"><button id="capacityStart">Start</button><button id="capacityStop">Stop</button><button id="capacityReset" class="reset">Reset</button></div></div><div class="threshold"><div class="threshold-head"><span>Cliff threshold</span><b id="cliffValue">150 mm</b></div><input id="cliffThreshold" type="range" min="50" max="500" step="5" value="150"></div><div class="segment-toggles" style="margin-top:11px;grid-template-columns:1fr"><label class="toggle"><input id="motionEmotions" type="checkbox" checked>Motion emotions</label></div></section>
<section class="card"><div class="section-title"><strong>Audio &amp; lighting</strong></div><div class="audio-row"><span class="audio-name"><b>Speaker</b><small>Output volume</small></span><input id="speakerVolume" type="range" min="0" max="100" step="5" value="70"><span class="audio-value" id="speakerValue">70%</span></div><div class="audio-row"><span class="audio-name"><b>Microphone</b><small>Input gain</small></span><input id="microphoneGain" type="range" min="1" max="3" step="1" value="1"><span class="audio-value" id="microphoneValue">1×</span><div class="vu-wrap"><div class="vu"><i id="micLevel"></i></div><span class="clip" id="micClip">LIVE</span></div></div><div class="audio-row"><span class="audio-name"><b>Screen</b><small>Backlight</small></span><input id="screenBrightness" type="range" min="10" max="100" step="5" value="75"><span class="audio-value" id="screenValue">75%</span></div><div class="audio-row"><span class="audio-name"><b>Status light</b><small>Edison LED · GPIO48</small></span><input id="statusLightBrightness" type="range" min="0" max="100" step="5" value="100"><span class="audio-value" id="statusLightValue">100%</span></div></section>
<section class="card"><div class="section-title"><strong>Displays</strong><span>Saved automatically</span></div><div class="display-actions"><button class="action" id="displayFlip" data-action="display_flip"><span class="icon">↕</span><span><b>Main display</b><small>Rotate 180°</small></span></button><button class="action" id="oledFlip" data-action="oled_flip"><span class="icon">↕</span><span><b>Secondary OLED</b><small>Rotate 180°</small></span></button></div><div class="display-settings"><label class="field"><span>OLED brand</span><input id="oledBrand" class="text-input" maxlength="20" value="Xiaozhi"></label><label class="field"><span>Distance prefix</span><input id="oledPrefix" class="text-input" maxlength="20" value="Dist"></label><label class="field"><span>Text size</span><select id="oledScale"><option value="1">Small · 1×</option><option value="2" selected>Medium · 2×</option><option value="3">Large · 3×</option></select></label><div class="segment-toggles"><label class="toggle"><input id="oledShowBrand" type="checkbox" checked>Brand</label><label class="toggle"><input id="oledShowState" type="checkbox" checked>Status</label><label class="toggle"><input id="oledShowDistance" type="checkbox" checked>Distance</label><label class="toggle"><input id="oledShowBattery" type="checkbox" checked>Battery</label><label class="toggle"><input id="oledShowVoltage" type="checkbox">Voltage</label><label class="toggle"><input id="oledShowCurrent" type="checkbox">Current</label></div></div></section>
<section class="card"><div class="section-title"><strong>Device</strong><span id="version">—</span></div><div class="device-grid"><div class="device-row"><span>Network</span><b id="ssid">—</b></div><div class="device-row"><span>Signal</span><b id="rssi">—</b></div><div class="device-row"><span>IP address</span><b id="ip">—</b></div><div class="device-row"><span>Internal RAM</span><b id="sram">—</b></div><div class="device-row"><span>PSRAM free</span><b id="psram">—</b></div><div class="device-row"><span>Camera health</span><b id="cameraHealth">—</b></div></div></section>
</div>
<div class="column center-column">
<section id="safety" class="card safety"><div><b>Table edge detected</b><small>Forward and turns are locked. Reverse only.</small></div><button data-stop>STOP</button></section>
<section class="card"><div class="section-title"><strong>Drive</strong><span id="durationLabel">250 ms</span></div><div class="dpad"><button class="control up" data-drive="forward" aria-label="Forward"><svg viewBox="0 0 24 24"><path d="M12 4 4 12h5v8h6v-8h5z"/></svg></button><button class="control left" data-drive="left" aria-label="Left"><svg viewBox="0 0 24 24"><path d="M12 4 4 12h5v8h6v-8h5z"/></svg></button><button class="control stop" data-stop>STOP</button><button class="control right" data-drive="right" aria-label="Right"><svg viewBox="0 0 24 24"><path d="M12 4 4 12h5v8h6v-8h5z"/></svg></button><button class="control down" data-drive="backward" aria-label="Backward"><svg viewBox="0 0 24 24"><path d="M12 4 4 12h5v8h6v-8h5z"/></svg></button></div><div class="range-row"><span>50 ms</span><input id="duration" type="range" min="50" max="2000" step="50" value="250"><span>2 sec</span></div><div class="range-row" style="margin-top:12px"><span>Speed</span><input id="motorSpeed" type="range" min="55" max="100" step="5" value="100"><span id="motorSpeedValue">100%</span></div><div class="motor-state"><span>Motion <b id="motion">Stopped</b></span><span>Queue <b id="queue">0</b></span><span>Time <b id="motorTime">0 ms</b></span></div><div class="progress"><i id="danceProgress"></i></div></section>
<section class="card"><div class="section-title"><strong>Quick actions</strong><span id="danceState">Ready</span></div><div class="actions"><button class="action" id="wakeAction" data-action="wake"><span class="icon">◉</span><span><b id="wakeLabel">Wake</b><small>Start or stop conversation</small></span></button><button class="action" id="idleAction" data-action="return_idle"><span class="icon">○</span><span><b>Return to idle</b><small>Stop activity safely</small></span></button><button class="action" id="danceAction" data-action="dance"><span class="icon">♪</span><span><b>Dance</b><small>30–50 randomized steps</small></span></button><button class="action" id="lightsAction" data-action="lights_toggle"><span class="icon">☀</span><span><b>Status lights</b><small>Toggle Edison LEDs</small></span></button><button class="action" data-action="audio_test"><span class="icon">♫</span><span><b>Audio test</b><small>Play a speaker tone</small></span></button><button class="action danger" data-action="wifi_config"><span class="icon">⌁</span><span><b>Wi-Fi config</b><small>Reconnect this robot</small></span></button><button class="action danger" data-action="reboot"><span class="icon">↯</span><span><b>Reboot</b><small>Restart this robot</small></span></button></div></section>
<section class="card"><div class="section-title"><strong>Emotions</strong><span>5-second preview</span></div><div class="emotion-grid"><button class="emotion" data-emotion="neutral">Neutral</button><button class="emotion" data-emotion="happy">Happy</button><button class="emotion" data-emotion="laughing">Laughing</button><button class="emotion" data-emotion="funny">Funny</button><button class="emotion" data-emotion="sad">Sad</button><button class="emotion" data-emotion="angry">Angry</button><button class="emotion" data-emotion="crying">Crying</button><button class="emotion" data-emotion="loving">Loving</button><button class="emotion" data-emotion="embarrassed">Embarrassed</button><button class="emotion" data-emotion="surprised">Surprised</button><button class="emotion" data-emotion="shocked">Shocked</button><button class="emotion" data-emotion="thinking">Thinking</button><button class="emotion" data-emotion="winking">Winking</button><button class="emotion" data-emotion="cool">Cool</button><button class="emotion" data-emotion="relaxed">Relaxed</button><button class="emotion" data-emotion="delicious">Delicious</button><button class="emotion" data-emotion="kissy">Kissy</button><button class="emotion" data-emotion="confident">Confident</button><button class="emotion" data-emotion="sleepy">Sleepy</button><button class="emotion" data-emotion="silly">Silly</button><button class="emotion" data-emotion="confused">Confused</button><button class="emotion" data-emotion="suspicious">Suspicious</button><button class="emotion" data-emotion="shake">Shake</button></div></section>
<section class="card"><div class="section-title"><strong>Browser camera</strong><span>VGA · JPEG</span></div><div class="camera-body"><div id="snapshot" class="snapshot"><span>No snapshot yet</span><img id="snapshotImage" alt="Camera snapshot"></div><div class="camera-copy"><p>Still capture or a light ~1 FPS browser preview. Live mode pauses outside Idle.</p><div class="camera-buttons"><button id="takeSnapshot" class="mini-button">Take photo</button><button id="browserLive" class="mini-button">Live</button><button id="liveCamera" class="mini-button" data-action="live_camera">Screen preview</button><button id="cameraFlip" class="mini-button" data-action="camera_flip">Flip camera</button></div><div id="snapshotMeta" class="camera-meta">Camera ready</div></div></div></section>
<p class="hint">Local network only · tap a direction to run for the selected time · STOP cancels</p>
</div>
<div class="column right-column"><section class="card log-card"><div class="log-head"><div class="log-state"><i></i><span id="logState">Live system log</span><span id="errorBadge" class="badge">0</span></div><div class="log-tools"><input id="logSearch" class="log-search" placeholder="Search logs"><select id="logFilter" class="log-select"><option value="all">All</option><option value="error">Errors</option><option value="warn">Warnings</option><option value="info">Info</option></select><button id="pauseLog" class="log-button">Pause</button><button id="downloadLog" class="log-button">Save</button><button id="clearLog" class="log-button">Clear</button></div></div><pre id="logOutput" class="log-output">Waiting for system logs…</pre><div class="log-foot"><span id="logSize">16 KB device buffer</span><label class="auto-scroll"><input id="autoScroll" type="checkbox" checked> Auto-scroll</label></div></section></div>
</div>
</main>
<button id="panicStop" class="panic-stop" data-stop>STOP MOTORS</button><div class="toast" id="toast"></div>
<script>
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s),toast=$('#toast');let toastTimer,statusTimer,logCursor=0,logStarted=false,logPaused=false,logPending=false,allLogs='',snapshotUrl='',browserLive=false,snapshotPending=false,lastState='starting',liveTimer;
function notify(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),1800)}
function fmtTime(sec){sec=Math.max(0,sec|0);const d=Math.floor(sec/86400),h=Math.floor(sec%86400/3600),m=Math.floor(sec%3600/60);return d?d+'d '+h+'h':h?h+'h '+m+'m':m+'m'}
function fmtCapacityTime(sec){sec=Math.max(0,sec|0);const h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;return h?h+'h '+m+'m':m?m+'m '+s+'s':s+'s'}
function fmtBytes(n){if(!Number.isFinite(n))return '—';return n>1048576?(n/1048576).toFixed(1)+' MB':Math.round(n/1024)+' KB'}
function fmtMs(ms){return ms>=1000?(ms/1000).toFixed(1)+' s':ms+' ms'}
async function action(name,extra={}){try{const r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:name,...extra})});const j=await r.json();if(!r.ok||!j.ok)throw Error(j.message||'Command failed');notify(j.message||'Done');queueStatus(120)}catch(e){notify(e.message||'Robot is offline')}}
function setRange(input,value,label,suffix){if(document.activeElement!==input&&Number.isFinite(value)){input.value=value;label.textContent=value+suffix}}
function renderStatus(j){
 const idle=j.state==='idle',m=j.motors||{},active=!!(m.moving||m.queued||m.sequence_active),cliff=!!j.cliff_detected,chatActive=['connecting','listening','speaking'].includes(j.state);lastState=j.state||'unknown';
 if(!idle&&browserLive)stopBrowserLive('Paused until Idle',true);$('#online').classList.add('ok');$('#online span').textContent='Online';$('#state').textContent=(j.state||'idle').replaceAll('_',' ');$('#camera').textContent=!j.camera_available?'Offline':j.live_camera?(idle?'Screen preview':'Preview paused'):(j.camera_flipped?'Flipped':'Normal');$('#distance').textContent=j.distance_valid?j.distance_mm+' mm':'—';$('#rangeState').textContent=cliff?'Edge · reverse only':j.distance_valid?'Floor detected':'No floor return';
 const batteryReady=!!j.battery_available&&!!j.battery_valid;$('#battery').textContent=!j.battery_available?'Offline':batteryReady?j.battery_percent+'% · '+Number(j.battery_voltage_v).toFixed(2)+' V':'Waiting';$('#power').textContent=batteryReady?Math.round(j.battery_current_ma)+' mA · '+(j.battery_power_mw/1000).toFixed(2)+' W':'—';const capacityMah=Number(j.battery_capacity_test_mah)||0,capacityActive=!!j.battery_capacity_test_active,capacityMeasuring=!!j.battery_capacity_test_measuring;$('#capacityResult').textContent=capacityMah.toFixed(1)+' mAh · '+fmtCapacityTime(j.battery_capacity_test_seconds||0);$('#capacityState').textContent=!j.battery_available?'INA219 unavailable':capacityMeasuring?'Measuring discharge':capacityActive?'Paused · unplug USB/charger':capacityMah>0?'Stopped · result saved':'Capacity test not started';$('#capacityStart').disabled=!j.battery_available||capacityActive;$('#capacityStop').disabled=!capacityActive;$('#capacityReset').disabled=!j.battery_available||(!capacityActive&&capacityMah===0);$('#capacityStart').textContent=capacityMah>0?'Resume':'Start';$('#capacityStart').classList.toggle('on',capacityMeasuring);
 const motionReady=!!j.motion_sensor_available&&!!j.motion_sensor_valid;$('#motionSensor').textContent=!j.motion_sensor_available?'Offline':motionReady?(j.motion_gesture||'steady')+' · '+Number(j.motion_roll_deg).toFixed(0)+'° / '+Number(j.motion_pitch_deg).toFixed(0)+'°':'Calibrating';$('#motionEmotions').disabled=!j.motion_sensor_available;if(document.activeElement!==$('#motionEmotions'))$('#motionEmotions').checked=!!j.motion_emotions_enabled;
 setRange($('#motorSpeed'),j.motor_speed,$('#motorSpeedValue'),'%'); $('#safety').classList.toggle('show',cliff);$$('[data-drive]').forEach(b=>b.disabled=cliff&&b.dataset.drive!=='backward');const oled=$('#oledState');oled.className='value health '+(j.oled_available?'good':'bad');oled.querySelector('span').textContent=j.oled_available?'Ready':'Offline';setRange($('#cliffThreshold'),j.cliff_edge_mm,$('#cliffValue'),' mm');setRange($('#speakerVolume'),j.speaker_volume,$('#speakerValue'),'%');setRange($('#microphoneGain'),j.microphone_gain,$('#microphoneValue'),'×');setRange($('#screenBrightness'),j.screen_brightness,$('#screenValue'),'%');setRange($('#statusLightBrightness'),j.status_light_brightness,$('#statusLightValue'),'%');$('#micLevel').style.width=Math.max(0,Math.min(100,j.microphone_level||0))+'%';$('#micClip').textContent=j.microphone_clipping?'CLIP':'LIVE';$('#micClip').classList.toggle('on',!!j.microphone_clipping);$('#liveCamera').classList.toggle('on',!!j.live_camera);$('#liveCamera').textContent=j.live_camera?(idle?'Stop screen preview':'Preview paused'):'Screen preview';$('#cameraFlip').classList.toggle('on',!!j.camera_flipped);$('#wakeAction').classList.toggle('on',chatActive);$('#wakeLabel').textContent=chatActive?'End chat':'Wake';$('#danceAction').classList.toggle('on',!!m.sequence_active);$('#lightsAction').classList.toggle('on',(j.status_light_brightness||0)>0);$$('[data-emotion]').forEach(b=>b.classList.toggle('on',b.dataset.emotion===(j.emotion||'neutral')));$('#displayFlip').classList.toggle('on',!!j.display_flipped);$('#oledFlip').classList.toggle('on',!!j.oled_flipped);$('#oledShowBrand').checked=!!j.oled_show_brand;$('#oledShowState').checked=!!j.oled_show_state;$('#oledShowDistance').checked=!!j.oled_show_distance;$('#oledShowBattery').checked=!!j.oled_show_battery;$('#oledShowVoltage').checked=!!j.oled_show_voltage;$('#oledShowCurrent').checked=!!j.oled_show_current;if(document.activeElement!==$('#oledScale'))$('#oledScale').value=String(j.oled_text_scale||2);if(document.activeElement!==$('#oledBrand')&&typeof j.oled_brand==='string')$('#oledBrand').value=j.oled_brand;if(document.activeElement!==$('#oledPrefix')&&typeof j.oled_distance_prefix==='string')$('#oledPrefix').value=j.oled_distance_prefix;$('#motion').textContent=m.faulted?'Fault':active?((m.direction||'moving')+(m.sequence_active?' · dance':'')):'Stopped';$('#queue').textContent=m.queued||0;$('#motorTime').textContent=fmtMs(m.remaining_ms||0);$('#panicStop').classList.toggle('show',active);const total=m.sequence_total||0,done=m.sequence_completed||0,pct=total?Math.min(100,done*100/total):0;$('#danceProgress').style.width=pct+'%';$('#danceState').textContent=m.sequence_active?(done+'/'+total+' steps'):'Ready';$('#uptime').textContent=fmtTime(j.uptime_sec);$('#version').textContent='v'+(j.version||'—');$('#ssid').textContent=j.ssid||'—';$('#rssi').textContent=j.rssi?j.rssi+' dBm':'—';$('#ip').textContent=j.ip||'—';$('#sram').textContent=fmtBytes(j.free_internal_bytes);$('#psram').textContent=fmtBytes(j.free_psram_bytes);$('#cameraHealth').textContent=j.camera_available?'Ready':'Offline';return active
}
async function pollStatus(){let fast=false;try{const r=await fetch('/api/status',{cache:'no-store'});if(!r.ok)throw Error();fast=renderStatus(await r.json())}catch(e){$('#online').classList.remove('ok');$('#online span').textContent='Offline'}finally{statusTimer=setTimeout(pollStatus,fast?300:1000)}}
function queueStatus(delay=0){clearTimeout(statusTimer);statusTimer=setTimeout(pollStatus,delay)}
const duration=$('#duration');duration.oninput=()=>$('#durationLabel').textContent=fmtMs(+duration.value);
const motorSpeed=$('#motorSpeed');motorSpeed.oninput=()=>$('#motorSpeedValue').textContent=motorSpeed.value+'%';motorSpeed.onchange=()=>action('motor_speed',{value:+motorSpeed.value});
[['speakerVolume','speakerValue','speaker_volume','%'],['microphoneGain','microphoneValue','microphone_gain','×'],['screenBrightness','screenValue','screen_brightness','%'],['statusLightBrightness','statusLightValue','status_light_brightness','%'],['cliffThreshold','cliffValue','cliff_threshold',' mm']].forEach(([i,l,a,s])=>{const input=$('#'+i),label=$('#'+l);input.oninput=()=>label.textContent=input.value+s;input.onchange=()=>action(a,{value:+input.value})});
[['oledShowBrand','oled_show_brand'],['oledShowState','oled_show_state'],['oledShowDistance','oled_show_distance'],['oledShowBattery','oled_show_battery'],['oledShowVoltage','oled_show_voltage'],['oledShowCurrent','oled_show_current']].forEach(([id,name])=>{$('#'+id).onchange=e=>action(name,{value:e.target.checked?1:0})});$('#oledScale').onchange=e=>action('oled_scale',{value:+e.target.value});[['oledBrand','oled_brand'],['oledPrefix','oled_prefix']].forEach(([id,name])=>{const input=$('#'+id);input.onchange=()=>action(name,{text:input.value});input.onkeydown=e=>{if(e.key==='Enter')input.blur()}});
$('#motionEmotions').onchange=e=>action('motion_emotions',{value:e.target.checked?1:0});
$('#capacityStart').onclick=()=>action('battery_capacity_start');$('#capacityStop').onclick=()=>action('battery_capacity_stop');$('#capacityReset').onclick=()=>{if(confirm('Reset the saved battery capacity measurement?'))action('battery_capacity_reset')};
$$('[data-drive]').forEach(btn=>{btn.onclick=()=>{if(!btn.disabled)action(btn.dataset.drive,{duration_ms:+duration.value})};btn.oncontextmenu=e=>e.preventDefault()});
function emergencyStop(){$$('[data-drive].active').forEach(b=>b.classList.remove('active'));fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:'{"action":"stop"}',keepalive:true}).catch(()=>{});queueStatus(120)}window.addEventListener('blur',emergencyStop);window.addEventListener('pagehide',emergencyStop);document.addEventListener('visibilitychange',()=>{if(document.hidden)emergencyStop()});$$('[data-stop]').forEach(b=>b.onclick=()=>action('stop'));$$('[data-action]').forEach(btn=>btn.onclick=()=>{const name=btn.dataset.action;if(name==='wifi_config'&&!confirm('Open Wi-Fi setup mode? This page will disconnect.'))return;if(name==='reboot'&&!confirm('Reboot the robot now? Motors will stop and this page will disconnect briefly.'))return;action(name)});
$$('[data-emotion]').forEach(btn=>btn.onclick=()=>action('emotion',{text:btn.dataset.emotion,duration_ms:5000}));
function clearSnapshot(){if(snapshotUrl){URL.revokeObjectURL(snapshotUrl);snapshotUrl=''}const img=$('#snapshotImage');img.removeAttribute('src');$('#snapshot').classList.remove('has-image')}async function captureSnapshot(silent=false){if(snapshotPending)return;snapshotPending=true;const button=$('#takeSnapshot'),meta=$('#snapshotMeta');button.disabled=true;if(!silent){button.textContent='Capturing…';meta.textContent='Waiting for camera'}try{const r=await fetch('/api/camera/snapshot?ts='+Date.now(),{cache:'no-store'});if(!r.ok){let msg='Capture failed';try{msg=(await r.json()).message||msg}catch(_){}throw Error(msg)}const blob=await r.blob();if(silent&&!browserLive)return;if(snapshotUrl)URL.revokeObjectURL(snapshotUrl);snapshotUrl=URL.createObjectURL(blob);const img=$('#snapshotImage');img.onload=()=>{meta.textContent=img.naturalWidth+' × '+img.naturalHeight+' · '+Math.round(blob.size/1024)+' KB'};img.src=snapshotUrl;$('#snapshot').classList.add('has-image')}catch(e){meta.textContent=e.message;if(!silent)notify(e.message);stopBrowserLive(e.message,true)}finally{snapshotPending=false;button.disabled=false;button.textContent='Take photo';if(browserLive)liveTimer=setTimeout(()=>captureSnapshot(true),850)}}function stopBrowserLive(message,clear=false){browserLive=false;clearTimeout(liveTimer);$('#browserLive').classList.remove('on');$('#browserLive').textContent='Live';if(clear)clearSnapshot();if(message)$('#snapshotMeta').textContent=message}$('#takeSnapshot').onclick=()=>captureSnapshot(false);$('#browserLive').onclick=()=>{if(browserLive){stopBrowserLive('Live preview stopped',true);return}if(lastState!=='idle'){notify('Browser live view is available only while Idle');return}browserLive=true;$('#browserLive').classList.add('on');$('#browserLive').textContent='Stop live';captureSnapshot(true)};
const logOutput=$('#logOutput'),pauseLog=$('#pauseLog'),logState=$('#logState'),autoScroll=$('#autoScroll');function stripAnsi(text){return text.replace(/\u001b\[[0-9;]*[A-Za-z]/g,'')}function logLevel(line){if(/(^|\s)E \(|\*\*\*ERROR|Guru Meditation|panic/i.test(line))return'error';if(/(^|\s)W \(/.test(line))return'warn';return'info'}function renderLogs(){const q=$('#logSearch').value.toLowerCase(),filter=$('#logFilter').value,lines=allLogs.split('\n'),visible=lines.filter(line=>(filter==='all'||logLevel(line)===filter)&&(!q||line.toLowerCase().includes(q))),pinned=logOutput.scrollHeight-logOutput.scrollTop-logOutput.clientHeight<30;logOutput.textContent=visible.join('\n')||'No matching logs';const errors=lines.filter(l=>logLevel(l)==='error').length,badge=$('#errorBadge');badge.textContent=errors;badge.classList.toggle('show',errors>0);$('#logSize').textContent=Math.round(allLogs.length/1024)+' KB cached · 16 KB device';if(autoScroll.checked&&pinned)logOutput.scrollTop=logOutput.scrollHeight}async function fetchLogs(){if(logPaused||logPending)return;logPending=true;try{const r=await fetch('/api/log?since='+logCursor,{cache:'no-store'});if(!r.ok)throw Error();const next=Number(r.headers.get('X-Log-Cursor')||logCursor),reset=r.headers.get('X-Log-Reset')==='1',text=stripAnsi(await r.text());if(!logStarted||reset){allLogs='';logStarted=true}if(text)allLogs+=text;if(allLogs.length>65536)allLogs=allLogs.slice(-65536);logCursor=next;logState.textContent='Live system log';try{localStorage.setItem('xiaozhiLogs',allLogs)}catch(_){}renderLogs()}catch(e){logState.textContent='Log disconnected'}finally{logPending=false}}
pauseLog.onclick=()=>{logPaused=!logPaused;pauseLog.textContent=logPaused?'Resume':'Pause';logState.textContent=logPaused?'Log paused':'Live system log';if(!logPaused)fetchLogs()};$('#clearLog').onclick=()=>{allLogs='';logStarted=true;try{localStorage.removeItem('xiaozhiLogs')}catch(_){}renderLogs()};$('#downloadLog').onclick=()=>{const a=document.createElement('a'),blob=new Blob([allLogs],{type:'text/plain'});a.href=URL.createObjectURL(blob);a.download='xiaozhi-'+new Date().toISOString().replaceAll(':','-')+'.log';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#logSearch').oninput=renderLogs;$('#logFilter').onchange=renderLogs;try{allLogs=localStorage.getItem('xiaozhiLogs')||'';if(allLogs){logStarted=true;renderLogs()}}catch(_){}
pollStatus();fetchLogs();setInterval(fetchLogs,650);
</script>
</body>
</html>)CONTROL";
